    @_mutmut_mutated(mutants_xǁDocumentationParserǁ_extract_markdown_sections__mutmut)
    def _extract_markdown_sections(self, markdown: str) -> list[dict[str, str]]:
        """마크다운에서 섹션 추출 (헤더 기반)"""
        sections = []
        # 마크다운 헤더 패턴 (# ## ### 등)
        header_pattern = re.compile(r"^(#{1,6})\s+(.+)$", re.MULTILINE)

        matches = list(header_pattern.finditer(markdown))
        for i, match in enumerate(matches):
            level = len(match.group(1))
            heading = match.group(2).strip()
            start = match.end()
            end = matches[i + 1].start() if i + 1 < len(matches) else len(markdown)
            section_content = markdown[start:end].strip()

            if section_content:
                sections.append(
                    {
                        "heading": heading,
                        "content": section_content[:3000],
                        "level": level,
                    }
                )

        return sections[:30]

