    def _extract_markdown_code_blocks(self, markdown: str) -> list[str]:
        """마크다운 코드 블록 추출 (``` 패턴)"""
        codes = []
        # ```language\ncode\n``` 패턴
        pattern = re.compile(r"```[\w]*\n(.*?)\n```", re.DOTALL)
